'use strict';

// MODULES //

var isSignalReference = require( '@stdlib/plot/vega/base/assert/is-signal-reference' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var copyJSON = require( './../../utils/copy_json.js' );
var signalName = require( './../../utils/signal_name.js' );


// VARIABLES //

var PROPS = [
	'domain',
	'domainCap',
	'domainColor',
	'domainDash',
	'domainDashOffset',
	'domainOpacity',
	'domainWidth',
	'grid',
	'gridCap',
	'gridColor',
	'gridDash',
	'gridDashOffset',
	'gridOpacity',
	'gridWidth',
	'tickBand',
	'tickCap',
	'tickColor',
	'tickCount',
	'tickDash',
	'tickDashOffset',
	'tickMinStep',
	'tickOffset',
	'tickOpacity',
	'ticks',
	'tickSize',
	'tickWidth',
	'title',
	'titleColor',
	'titleFont',
	'titleOpacity'
];


// MAIN //

/**
* Returns a transformed axis schema containing signals for use in conjunction with UI components.
*
* ## Notes
*
* -   The function mutates the provided list of signals.
*
* @private
* @param {Object} schema - axis schema
* @param {Array} signals - list of signals
* @param {Object} defaults - axis schema defaults
* @param {string} prefix - signal prefix
* @returns {Object} transformed schema
*/
function transform( schema, signals, defaults, prefix ) {
	var value;
	var name;
	var out;
	var k;
	var v;
	var i;

	out = copyJSON( schema );
	for ( i = 0; i < PROPS.length; i++ ) {
		k = PROPS[ i ];
		v = schema[ k ];
		if ( !isSignalReference( v ) ) {
			name = signalName( prefix+k );
			value = ( isUndefined( v ) ) ? defaults[ k ].default : v;

			if ( k === 'tickCount' ) {
				signals.push({
					'name': name,
					'value': ( value === '' ) ? void 0 : value
				});
			} else {
				signals.push({
					'name': name,
					'value': value
				});
			}

			// FIXME: Vega does not currently support signal updates for structural properties like `domain`, `grid` & `ticks`. As a workaround, we keep them statically `true` and dynamically hide them by dropping their respective opacities to 0 when unchecked.
			if ( k === 'domain' ) {
				out[ k ] = true;
			} else if ( k === 'domainOpacity' ) {
				out[ k ] = {
					'signal': signalName( prefix+'domain' ) + ' ? ' + name + ' : 0'
				};
			} else if ( k === 'grid' ) {
				out[ k ] = true;
			} else if ( k === 'gridOpacity' ) {
				out[ k ] = {
					'signal': signalName( prefix+'grid' ) + ' ? ' + name + ' : 0'
				};
			} else if ( k === 'ticks' ) {
				out[ k ] = true;
			} else if ( k === 'tickOpacity' ) {
				out[ k ] = {
					'signal': signalName( prefix+'ticks' ) + ' ? ' + name + ' : 0'
				};
			} else {
				out[ k ] = {
					'signal': name
				};
			}
		}
	}
	return out;
}


// EXPORTS //

module.exports = transform;
